// Single thread, cooperative. A blocking task occupies `cost` ticks.
function runLoop(tasks) {
  const out = [];
  let t = 0;
  for (const task of tasks) {
    for (let i = 0; i < task.cost; i++) { t++; }
    out.push(task.id + '@' + t);
  }
  return out;
}
const ready = [
  { id: 'A', cost: 1 },   // quick I/O callback
  { id: 'BLOCK', cost: 5 }, // synchronous CPU hog: holds the only thread
  { id: 'B', cost: 1 },   // was ready at tick 2, but had to wait
  { id: 'C', cost: 1 },
];
console.log(runLoop(ready).join(' '));
